from pathlib import Path
import base64, zlib, re

DATA = ''''''
java = zlib.decompress(base64.b64decode(DATA)).decode('utf-8')
Path('app/src/main/java/lt/deikai/balsiulektuvas/MainActivity.java').write_text(java, encoding='utf-8')

g = Path('app/build.gradle')
gs = g.read_text(encoding='utf-8')
gs = re.sub(r'versionCode\s+\d+', 'versionCode 21', gs)
gs = re.sub(r'versionName\s+"[^"]+"', 'versionName "1.21"', gs)
g.write_text(gs, encoding='utf-8')
